dtsPropsFor.Button:
/** Visual emphasis. @default "primary" */
  variant?: "primary" | "secondary" | "ghost";
  /** Control height + padding. @default "md" */
  size?: "sm" | "md" | "lg";
  children: React.ReactNode;
  className?: string;
  disabled?: boolean;
  type?: "button" | "submit" | "reset";
  onClick?: React.MouseEventHandler<HTMLButtonElement>;

dtsPropsFor.Card:
/** Render the app's signature corner-bracket accents (gold L-marks). @default false */
  cornerAccent?: boolean;
  /** Elevation surface. @default "card" */
  surface?: "card" | "elevated" | "grouped";
  className?: string;
  children: React.ReactNode;

dtsPropsFor.Badge:
/** Accent family. Ignored when `color` is set. @default "gold" */
  tone?: "gold" | "sage" | "silver" | "neutral";
  /** Override with a raw category-bucket color (hex or CSS var, e.g. var(--color-cat-emerald)) for the app's category pills. */
  color?: string;
  /** Leading status dot in the current text color. @default false */
  dot?: boolean;
  className?: string;
  children: React.ReactNode;

dtsPropsFor.SectionHeading:
/** Small uppercase label above the title (rendered as a gold Badge). */
  eyebrow?: string;
  title: React.ReactNode;
  /** Supporting paragraph below the title. */
  subtitle?: React.ReactNode;
  /** @default "left" */
  align?: "left" | "center";
  className?: string;

dtsPropsFor.Stat:
/** Caption above the figure. */
  label?: React.ReactNode;
  /** The headline figure — rendered with mono, tabular digits. */
  value: React.ReactNode;
  /** Optional delta. direction "up" = spending rose (red); "down" = spending fell (green). */
  delta?: { direction: "up" | "down"; value: React.ReactNode };
  className?: string;

dtsPropsFor.Input:
/** Render in the error state (pink ring). @default false */
  invalid?: boolean;
  type?: string;
  placeholder?: string;
  value?: string;
  defaultValue?: string;
  onChange?: React.ChangeEventHandler<HTMLInputElement>;
  className?: string;
  "aria-label"?: string;
